{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
}
|group#visual| "V3 · Approval, no-op and replay" { layout: grid; columns: repeat(2); gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "First request token ·\nbusiness change" { width: 240; } [
    |cell#detail| "Before: pending. Required SET:\napproved. Commit retains the outcome\nand one business-change fact."
  ]
  |box#n2| "Fresh request token ·\nbusiness no-op" { width: 240; } [
    |cell#detail| "Before: approved. SET verifies no-op.\nA new outcome persists; business\nversion and event count do not\nadvance."
  ]
  |box#n3| "Original request token ·\nreplay" { width: 240; } [
    |cell#detail| "Return the exact retained first\noutcome under current authorization.\nDo not execute again or substitute the\nfresh no-op."
  ]
]
